-- Verified reception / quotation records for the public "名人与书籍评价" archive.
-- Sources are preserved as structured JSON so the public UI can show the quotation first and the source second.

on conflict (slug) do update set zh=excluded.zh, sources=excluded.sources, category=excluded.category, status='published', updated_at=now();

update public.entries
set zh=jsonb_set(zh,'{meta}',(coalesce(zh->'meta','{}'::jsonb)-'quote'-'quote_original'-'quote_work'-'quote_context')||jsonb_build_object('quote','厂窑至此，集大成矣！','quote_original','厂窑至此，集大成矣！','quote_work','《陶说》／唐英相关制瓷记述','quote_context','唐英评价景德镇厂窑制瓷发展至此，已达到集大成的程度。'),true), updated_at=now()
where slug='tang-ying';
